import { devtools, persist } from 'zustand/middleware';

interface Offer {
  id: string;
  vehicleId: string;
  status: 'pending' | 'approved' | 'declined';
  totalPrice: number;
  tradeInValue: number;
  monthlyPayment: number;
  managerNotes: string;
  lastUpdatedBy: string;
  lastUpdatedAt: string;
}

interface OfferStore {
  offer: Offer | null;
  isLoading: boolean;
  error: string | null;
  // Actions
  setOffer: (offer: Offer) => void;
  patchOffer: (patch: Partial<Offer>) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  reset: () => void;
}

export const useOfferStore = create<OfferStore>()(
  devtools(
    (set) => ({
      offer: null,
      isLoading: false,
      error: null,

      setOffer: (offer) => set({ offer }, false, 'setOffer'),

      // Key pattern: patch only what changed — critical for WebSocket updates
      patchOffer: (patch) =>
        set(
          (state) => ({ offer: state.offer ? { ...state.offer, ...patch } : null }),
          false,
          'patchOffer'
        ),

      setLoading: (isLoading) => set({ isLoading }, false, 'setLoading'),
      setError: (error) => set({ error }, false, 'setError'),
      reset: () => set({ offer: null, isLoading: false, error: null }, false, 'reset'),
    }),
    { name: 'OfferStore' }
  )
);`})]}),a.jsxs("p",{children:["The ",a.jsx("code",{className:"text-purple-300 bg-gray-800 px-1.5 py-0.5 rounded text-sm",children:"patchOffer"})," action is the workhorse here. When a WebSocket event fires with a partial update — say, just the price changed — we don't replace the entire offer object. We merge only what changed. This keeps re-renders surgical."]}),a.jsxs("h2",{className:"text-2xl font-bold mt-10 mb-4 flex items-center gap-2",children:[a.jsx(dc,{className:"text-cyan-400"})," Selective Subscriptions: Preventing Unnecessary Re-Renders"]}),a.jsxs("p",{children:["This is where Zustand earns its keep. Instead of subscribing to the whole store, components select ",a.jsx("em",{children:"only the slice they display"}),":"]}),a.jsxs("pre",{className:"bg-gray-900 rounded-lg p-4 text-sm overflow-x-auto my-4",children:[a.jsxs("div",{className:"flex items-center gap-2 mb-3 pb-2 border-b border-gray-700",children:[a.jsx(Lt,{className:"text-blue-400",size:14}),a.jsx("span",{className:"text-xs text-green-400 uppercase tracking-widest",children:"src/components/PriceDisplay.tsx"})]}),a.jsx("code",{className:"language-typescript",children:`// ✅ GOOD: Component only re-renders when totalPrice changes
